window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-55d35a0a85431175"]={"versions": [{"id": "FIG-55d35a0a85431175", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-Strukturdiagramm zur Veranschaulichung der Wertespezifikation (Value Specification) verschachtelter zusammengesetzter Datentypen in der AUTOSAR Software Component Template (SWCT). Das Diagramm visualisiert die hierarchische Datenorganisation einer Array-Struktur, deren Elemente komplexe Record-Typen (<code>struct</code>) sind, welche wiederum primitive Member sowie eingebettete Arrays enthalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine verschachtelte Hierarchie von Datentyp- und Wertstrukturen:</p>\n<ul class=\"fig-list\">\n<li>Äußere Ebene: Ein übergeordnetes <code>array</code> bestehend aus zwei identisch strukturierten <code>struct</code>-Elementen (Array-Länge 2).</li>\n<li>Mittlere Ebene: Jedes <code>struct</code>-Element enthält zwei Member:</li>\n<li>Ein skalares/primitives Feld <code>a</code> mit dem zugewiesenen Initial- oder Spezifikationswert <code>1</code>.</li>\n<li>Ein eingebettetes Member <code>array</code>.</li>\n<li>Innere Ebene: Das innere <code>array</code> besteht aus jeweils drei Feldern <code>b</code> (Array-Länge 3), denen die Werte <code>1</code>, <code>0</code> und <code>0</code> zugewiesen sind. Die ovalen Marker an den oberen rechten Ecken der Elemente bezeichnen die jeweiligen numerischen Elementwerte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturschaubild ohne Laufzeitsequenz oder Kontrollfluss. Es repräsentiert die Instanziierungs- und Initialisierungsstruktur von <code>ValueSpecification</code> (bzw. <code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>, <code>NumericalValueSpecification</code>), bei der die Baumstruktur der Werte exakt der Verschachtelungstiefe der <code>ApplicationDataType</code>- bzw. <code>ImplementationDataType</code>-Definition folgt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für Modellierungs- und Generierungswerkzeuge zur konsistenten Abbildung tiefer Wertespezifikationen in ARXML. Die Hierarchie veranschaulicht die Korrespondenz zwischen zusammengesetzten <code>ValueSpecification</code>-Klassen: Das äußere <code>ArrayValueSpecification</code> aggregiert zwei <code>RecordValueSpecification</code>-Elemente; jede <code>RecordValueSpecification</code> aggregiert eine <code>NumericalValueSpecification</code> (für <code>a</code>) sowie eine innere <code>ArrayValueSpecification</code>, welche ihrerseits drei <code>NumericalValueSpecification</code>-Elemente (für <code>b</code>) aggregiert. Werkzeuge müssen sicherstellen, dass Dimensionen und Typkompatibilitäten der verschachtelten Werte exakt mit der Datentypdeklaration übereinstimmen.</p>"}, {"id": "FIG-ca4339afdaf0f24f", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-Strukturdiagramm zur Veranschaulichung der Wertespezifikation (Value Specification) verschachtelter zusammengesetzter Datentypen in der AUTOSAR Software Component Template (SWCT). Das Diagramm visualisiert die hierarchische Datenorganisation einer Array-Struktur, deren Elemente komplexe Record-Typen (<code>struct</code>) sind, welche wiederum primitive Member sowie eingebettete Arrays enthalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine verschachtelte Hierarchie von Datentyp- und Wertstrukturen:</p>\n<ul class=\"fig-list\">\n<li>Äußere Ebene: Ein übergeordnetes <code>array</code> bestehend aus zwei identisch strukturierten <code>struct</code>-Elementen (Array-Länge 2).</li>\n<li>Mittlere Ebene: Jedes <code>struct</code>-Element enthält zwei Member:</li>\n<li>Ein skalares/primitives Feld <code>a</code> mit dem zugewiesenen Initial- oder Spezifikationswert <code>1</code>.</li>\n<li>Ein eingebettetes Member <code>array</code>.</li>\n<li>Innere Ebene: Das innere <code>array</code> besteht aus jeweils drei Feldern <code>b</code> (Array-Länge 3), denen die Werte <code>1</code>, <code>0</code> und <code>0</code> zugewiesen sind. Die ovalen Marker an den oberen rechten Ecken der Elemente bezeichnen die jeweiligen numerischen Elementwerte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturschaubild ohne Laufzeitsequenz oder Kontrollfluss. Es repräsentiert die Instanziierungs- und Initialisierungsstruktur von <code>ValueSpecification</code> (bzw. <code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>, <code>NumericalValueSpecification</code>), bei der die Baumstruktur der Werte exakt der Verschachtelungstiefe der <code>ApplicationDataType</code>- bzw. <code>ImplementationDataType</code>-Definition folgt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für Modellierungs- und Generierungswerkzeuge zur konsistenten Abbildung tiefer Wertespezifikationen in ARXML. Die Hierarchie veranschaulicht die Korrespondenz zwischen zusammengesetzten <code>ValueSpecification</code>-Klassen: Das äußere <code>ArrayValueSpecification</code> aggregiert zwei <code>RecordValueSpecification</code>-Elemente; jede <code>RecordValueSpecification</code> aggregiert eine <code>NumericalValueSpecification</code> (für <code>a</code>) sowie eine innere <code>ArrayValueSpecification</code>, welche ihrerseits drei <code>NumericalValueSpecification</code>-Elemente (für <code>b</code>) aggregiert. Werkzeuge müssen sicherstellen, dass Dimensionen und Typkompatibilitäten der verschachtelten Werte exakt mit der Datentypdeklaration übereinstimmen.</p>"}, {"id": "FIG-c21f4755b78a5c33", "releases": ["R19-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-Strukturdiagramm zur Veranschaulichung der Wertespezifikation (Value Specification) verschachtelter zusammengesetzter Datentypen in der AUTOSAR Software Component Template (SWCT). Das Diagramm visualisiert die hierarchische Datenorganisation einer Array-Struktur, deren Elemente komplexe Record-Typen (<code>struct</code>) sind, welche wiederum primitive Member sowie eingebettete Arrays enthalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine verschachtelte Hierarchie von Datentyp- und Wertstrukturen:</p>\n<ul class=\"fig-list\">\n<li>Äußere Ebene: Ein übergeordnetes <code>array</code> bestehend aus zwei identisch strukturierten <code>struct</code>-Elementen (Array-Länge 2).</li>\n<li>Mittlere Ebene: Jedes <code>struct</code>-Element enthält zwei Member:</li>\n<li>Ein skalares/primitives Feld <code>a</code> mit dem zugewiesenen Initial- oder Spezifikationswert <code>1</code>.</li>\n<li>Ein eingebettetes Member <code>array</code>.</li>\n<li>Innere Ebene: Das innere <code>array</code> besteht aus jeweils drei Feldern <code>b</code> (Array-Länge 3), denen die Werte <code>1</code>, <code>0</code> und <code>0</code> zugewiesen sind. Die ovalen Marker an den oberen rechten Ecken der Elemente bezeichnen die jeweiligen numerischen Elementwerte.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturschaubild ohne Laufzeitsequenz oder Kontrollfluss. Es repräsentiert die Instanziierungs- und Initialisierungsstruktur von <code>ValueSpecification</code> (bzw. <code>ArrayValueSpecification</code>, <code>RecordValueSpecification</code>, <code>NumericalValueSpecification</code>), bei der die Baumstruktur der Werte exakt der Verschachtelungstiefe der <code>ApplicationDataType</code>- bzw. <code>ImplementationDataType</code>-Definition folgt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Referenz für Modellierungs- und Generierungswerkzeuge zur konsistenten Abbildung tiefer Wertespezifikationen in ARXML. Die Hierarchie veranschaulicht die Korrespondenz zwischen zusammengesetzten <code>ValueSpecification</code>-Klassen: Das äußere <code>ArrayValueSpecification</code> aggregiert zwei <code>RecordValueSpecification</code>-Elemente; jede <code>RecordValueSpecification</code> aggregiert eine <code>NumericalValueSpecification</code> (für <code>a</code>) sowie eine innere <code>ArrayValueSpecification</code>, welche ihrerseits drei <code>NumericalValueSpecification</code>-Elemente (für <code>b</code>) aggregiert. Werkzeuge müssen sicherstellen, dass Dimensionen und Typkompatibilitäten der verschachtelten Werte exakt mit der Datentypdeklaration übereinstimmen.</p>"}], "trans": [{"from": "FIG-55d35a0a85431175", "to": "FIG-ca4339afdaf0f24f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ca4339afdaf0f24f", "to": "FIG-c21f4755b78a5c33", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c21f4755b78a5c33", "to": "FIG-ca4339afdaf0f24f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
